export function createControls(canvas,joystick,stick,onAction){const state={x:0,y:0,yaw:0,pitch:-.22,attack:false,dodge:false};let moveId=null,lookId=null,origin=null,lastX=0,lastY=0;const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));function setStick(dx,dy){const max=43,l=Math.hypot(dx,dy)||1,scale=Math.min(1,max/l);stick.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;state.x=dx/max*scale;state.y=dy/max*scale;}
function resetMove(){moveId=null;state.x=state.y=0;stick.style.transform='translate(0px,0px)';joystick.classList.remove('active');}
function down(e){if(e.target.closest('button,.skillbar,.pause-card'))return;const r=canvas.getBoundingClientRect();const x=e.clientX-r.left;if(x<r.width*.48&&moveId===null){moveId=e.pointerId;origin={x:e.clientX,y:e.clientY};joystick.classList.add('active');joystick.style.left=`${Math.max(12,e.clientX-65)}px`;joystick.style.bottom='auto';joystick.style.top=`${Math.max(80,e.clientY-65)}px`;setStick(0,0);}else if(lookId===null){lookId=e.pointerId;lastX=e.clientX;lastY=e.clientY;}try{canvas.setPointerCapture(e.pointerId)}catch{}}
function move(e){if(e.pointerId===moveId&&origin){setStick(e.clientX-origin.x,e.clientY-origin.y);}else if(e.pointerId===lookId){state.yaw-=(e.clientX-lastX)*.006;state.pitch=clamp(state.pitch+(e.clientY-lastY)*.003,-.75,.2);lastX=e.clientX;lastY=e.clientY;}}
function up(e){if(e.pointerId===moveId)resetMove();if(e.pointerId===lookId)lookId=null;}
canvas.addEventListener('pointerdown',down);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',up);canvas.addEventListener('pointercancel',up);document.getElementById('attack').addEventListener('pointerdown',e=>{e.preventDefault();state.attack=true;onAction('attack');});document.getElementById('attack').addEventListener('pointerup',()=>state.attack=false);document.getElementById('dodge').addEventListener('pointerdown',e=>{e.preventDefault();state.dodge=true;onAction('dodge');setTimeout(()=>state.dodge=false,250);});document.querySelectorAll('[data-skill]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();onAction('skill',b.dataset.skill);}));return {state,dispose(){canvas.removeEventListener('pointerdown',down);canvas.removeEventListener('pointermove',move);canvas.removeEventListener('pointerup',up);}};}
